// app/settings/actions.ts
'use server'
export async function updateProfile(formData: FormData) {
  const supabase = createClient() // cookie-bound
  const data = Object.fromEntries(formData)
  await supabase.from('profiles').update(data).eq('id', (await supabase.auth.getUser()).data.user!.id)
}
```
profiles has columns: id, display_name, avatar_url, role, tenant_id.
